package com.rezoxnemesis.videostudio;

import org.json.JSONArray;
import org.json.JSONObject;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.robolectric.RobolectricTestRunner;
import org.robolectric.RuntimeEnvironment;
import org.robolectric.annotation.Config;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.UUID;
import java.util.zip.*;
import static org.junit.Assert.*;

@RunWith(RobolectricTestRunner.class)
@Config(sdk=33,manifest=Config.NONE)
public class OpenPipelineArtifactTest {
    private File temp()throws Exception {return Files.createTempDirectory("open-pipeline-test-").toFile();}
    private JSONObject request()throws Exception {return new JSONObject().put("schema",OpenPipelineArtifacts.REQUEST_SCHEMA).put("requestId","req_test").put("projectId","project_test").put("sourceProjectUpdatedAt",12).put("backend","frame_sequence").put("controls",new JSONObject().put("fps",24).put("width",720).put("height",1280)).put("sources",new JSONArray());}
    private File result(File parent,JSONObject request,String requestSha,String fileSha,boolean extra)throws Exception {
        byte[] bytes="video payload".getBytes(StandardCharsets.UTF_8);JSONObject record=new JSONObject().put("path","output.mp4").put("role","video").put("mime","video/mp4").put("bytes",bytes.length).put("sha256",fileSha);
        JSONObject manifest=new JSONObject().put("schema",OpenPipelineArtifacts.RESULT_SCHEMA).put("requestId",request.getString("requestId")).put("projectId",request.getString("projectId")).put("sourceProjectUpdatedAt",request.getLong("sourceProjectUpdatedAt")).put("requestSha256",requestSha).put("jobId","job_test").put("state","completed").put("files",new JSONArray().put(record));File target=new File(parent,"result.vsresult");
        try(ZipOutputStream zip=new ZipOutputStream(new FileOutputStream(target))){OpenPipelineArtifacts.entry(zip,"manifest.json",manifest.toString().getBytes(StandardCharsets.UTF_8));OpenPipelineArtifacts.entry(zip,"output.mp4",bytes);if(extra)OpenPipelineArtifacts.entry(zip,"hidden.json","{}".getBytes(StandardCharsets.UTF_8));}return target;
    }
    @Test public void exactBoundResultExtractsBytesButDoesNotCertifyVideoQuality()throws Exception {File root=temp();JSONObject req=request();String requestHash=OpenPipelineArtifacts.hash(req.toString().getBytes(StandardCharsets.UTF_8));File archive=result(root,req,requestHash,OpenPipelineArtifacts.hash("video payload".getBytes(StandardCharsets.UTF_8)),false);File stage=new File(root,"stage");JSONObject verified=OpenPipelineArtifacts.verifyResult(archive,stage,req,requestHash);assertEquals("req_test",verified.getString("requestId"));assertEquals("video payload",new String(Files.readAllBytes(new File(stage,"output.mp4").toPath()),StandardCharsets.UTF_8));assertFalse(verified.has("nativeRendered"));}
    @Test public void corruptOrUnlistedOutputsNeverBecomeInstalled()throws Exception {File root=temp();JSONObject req=request();String hash=OpenPipelineArtifacts.hash(req.toString().getBytes(StandardCharsets.UTF_8));File archive=result(root,req,hash,"0".repeat(64),false);File stage=new File(root,"stage");try{OpenPipelineArtifacts.verifyResult(archive,stage,req,hash);fail("Corrupt payload accepted");}catch(IllegalArgumentException expected){}assertFalse(stage.exists());archive.delete();archive=result(root,req,hash,OpenPipelineArtifacts.hash("video payload".getBytes(StandardCharsets.UTF_8)),true);try{OpenPipelineArtifacts.verifyResult(archive,stage,req,hash);fail("Unlisted payload accepted");}catch(IllegalArgumentException expected){}assertFalse(stage.exists());}
    @Test public void wrongSourceRevisionOrRequestHashRefusesResult()throws Exception {File root=temp();JSONObject req=request();String hash=OpenPipelineArtifacts.hash(req.toString().getBytes(StandardCharsets.UTF_8));File archive=result(root,req,hash,OpenPipelineArtifacts.hash("video payload".getBytes(StandardCharsets.UTF_8)),false);req.put("sourceProjectUpdatedAt",13);try{OpenPipelineArtifacts.verifyResult(archive,new File(root,"stage"),req,hash);fail("Stale project accepted");}catch(IllegalArgumentException expected){}req.put("sourceProjectUpdatedAt",12);try{OpenPipelineArtifacts.verifyResult(archive,new File(root,"stage2"),req,"0".repeat(64));fail("Foreign request accepted");}catch(IllegalArgumentException expected){}}
    @Test public void pathsCredentialsAndBackendControlsAreStrict()throws Exception {for(String path:new String[]{"../secret","a/../secret","/absolute","a\\b","a//b"})try{OpenPipelineArtifacts.path(path);fail(path);}catch(IllegalArgumentException expected){}try{OpenPipelineStore.endpoint("https://user:secret@example.com");fail("Embedded auth accepted");}catch(IllegalArgumentException expected){}try{OpenPipelineStore.endpoint("http://example.com");fail("Plain HTTP accepted");}catch(IllegalArgumentException expected){}JSONObject bad=new JSONObject().put("fps",24).put("width",720).put("height",1280).put("executable","evil");try{OpenPipelineOperations.validateControls("frame_sequence",bad);fail("Executable control accepted");}catch(IllegalArgumentException expected){}assertEquals("{\"a\":1,\"b\":2}",OpenPipelineOperations.canonical(new JSONObject().put("b",2).put("a",1)));}
    @Test public void requestExportFreezesSelectedOwnedBytesAndRejectsIdReuse()throws Exception {android.content.Context context=RuntimeEnvironment.getApplication();ProjectStore store=new ProjectStore(context);ProjectStore.Project project=store.create("Open pipeline integrity source");File source=new File(context.getFilesDir(),"source_"+UUID.randomUUID()+".png");Files.write(source.toPath(),new byte[]{1,2,3,4});ProjectStore.Asset asset=store.registerGeneratedAsset(project,android.net.Uri.fromFile(source),source.getName(),"reference",false);asset.mime="image/png";asset.sizeBytes=4;store.save(project);String id="req_"+UUID.randomUUID();JSONObject p=new JSONObject().put("projectId",project.id).put("sourceProjectUpdatedAt",project.updatedAt).put("requestId",id).put("backend","frame_sequence").put("controls",new JSONObject().put("fps",24).put("width",720).put("height",1280)).put("assetIds",new JSONArray().put(asset.id));JSONObject first=OpenPipelineOperations.execute(context,store,"open_pipeline_export_request",p,null);JSONObject replay=OpenPipelineOperations.execute(context,store,"open_pipeline_export_request",p,null);assertEquals(first.getString("archiveSha256"),replay.getString("archiveSha256"));assertEquals(project.updatedAt,store.get(project.id).updatedAt);OpenPipelineStore journal=new OpenPipelineStore(context);JSONObject stored=journal.get(id);assertFalse(stored.getJSONObject("request").toString().contains("file:"));p.getJSONObject("controls").put("fps",30);try{OpenPipelineOperations.execute(context,store,"open_pipeline_export_request",p,null);fail("Conflicting id accepted");}catch(IllegalStateException expected){assertTrue(expected.getMessage().contains("IDEMPOTENCY_CONFLICT"));}p.getJSONObject("controls").put("fps",24);Files.write(source.toPath(),new byte[]{9,2,3,4});try{OpenPipelineOperations.execute(context,store,"open_pipeline_export_request",p,null);fail("Changed source accepted");}catch(IllegalStateException expected){assertTrue(expected.getMessage().contains("SOURCE_BYTES_CHANGED"));}}
    private JSONObject cogControls()throws Exception {return new JSONObject().put("prompt","A river valley").put("width",64).put("height",64).put("numFrames",9).put("fps",8).put("seed",42).put("numInferenceSteps",2).put("guidanceScale",6.0);}
    @Test public void videoConditioningRequiresExplicitStrengthAndExactlyOneOwnedMp4()throws Exception {
        JSONObject text=OpenPipelineOperations.validateControls("cogvideox",cogControls());assertFalse("Old text requests retain their unchanged byte shape",text.has("mode"));ProjectStore.Project source=new ProjectStore.Project();ProjectStore.Asset video=new ProjectStore.Asset();video.id="owned_video";video.mime="video/mp4";video.durationMs=1000;source.assets.add(video);JSONArray one=new JSONArray().put(video.id);OpenPipelineOperations.validateCogSources(text,new JSONArray(),source);assertThrows(IllegalArgumentException.class,()->OpenPipelineOperations.validateCogSources(text,one,source));
        JSONObject videoControls=cogControls().put("mode","video_to_video");assertThrows(IllegalArgumentException.class,()->OpenPipelineOperations.validateControls("cogvideox",videoControls));videoControls.put("strength",.8);JSONObject checked=OpenPipelineOperations.validateControls("cogvideox",videoControls);OpenPipelineOperations.validateCogSources(checked,one,source);assertThrows(IllegalArgumentException.class,()->OpenPipelineOperations.validateCogSources(checked,new JSONArray(),source));assertThrows(IllegalArgumentException.class,()->OpenPipelineOperations.validateCogSources(checked,new JSONArray().put(video.id).put(video.id),source));assertThrows(IllegalArgumentException.class,()->OpenPipelineOperations.validateCogSources(checked,new JSONArray().put("foreign_video"),source));video.mime="image/png";assertThrows(IllegalArgumentException.class,()->OpenPipelineOperations.validateCogSources(checked,one,source));videoControls.put("strength",.01);assertThrows(IllegalArgumentException.class,()->OpenPipelineOperations.validateControls("cogvideox",videoControls));videoControls.put("strength",1.01);assertThrows(IllegalArgumentException.class,()->OpenPipelineOperations.validateControls("cogvideox",videoControls));videoControls.put("strength",.05).put("numInferenceSteps",1);IllegalArgumentException zeroSteps=assertThrows(IllegalArgumentException.class,()->OpenPipelineOperations.validateControls("cogvideox",videoControls));assertTrue(zeroSteps.getMessage().contains("V2V_ZERO_DENOISING_STEPS"));assertThrows(IllegalArgumentException.class,()->OpenPipelineOperations.validateControls("cogvideox",cogControls().put("strength",.8)));assertThrows(IllegalArgumentException.class,()->OpenPipelineOperations.validateControls("cogvideox",cogControls().put("mode","image_to_video")));assertThrows(IllegalArgumentException.class,()->OpenPipelineOperations.validateControls("cogvideox",cogControls().put("numFrames",8)));
    }
    @Test public void referenceClipSnapshotRetainsExactHashAndRejectsChangedStrengthReuse()throws Exception {
        android.content.Context context=RuntimeEnvironment.getApplication();ProjectStore store=new ProjectStore(context);ProjectStore.Project project=store.create("Video conditioned request binding");File source=new File(context.getFilesDir(),"reference_"+UUID.randomUUID()+".mp4");byte[] bytes="owned explicit clip bytes for artifact-only validation".getBytes(StandardCharsets.UTF_8);Files.write(source.toPath(),bytes);ProjectStore.Asset asset=store.registerGeneratedAsset(project,android.net.Uri.fromFile(source),source.getName(),"motion_reference",false);asset.mime="video/mp4";asset.durationMs=1000;asset.sizeBytes=bytes.length;store.save(project);String id="v2v_"+UUID.randomUUID();JSONObject p=new JSONObject().put("projectId",project.id).put("sourceProjectUpdatedAt",project.updatedAt).put("requestId",id).put("backend","cogvideox").put("controls",cogControls().put("mode","video_to_video").put("strength",.8)).put("assetIds",new JSONArray().put(asset.id));JSONObject exported=OpenPipelineOperations.execute(context,store,"open_pipeline_export_request",p,null);JSONObject request=new OpenPipelineStore(context).get(id).getJSONObject("request");assertEquals("video_to_video",request.getJSONObject("controls").getString("mode"));JSONObject reference=request.getJSONArray("sources").getJSONObject(0);assertEquals("video/mp4",reference.getString("mime"));assertEquals("inputs/0.mp4",reference.getString("path"));assertEquals(OpenPipelineArtifacts.hash(bytes),reference.getString("sha256"));assertFalse(request.toString().contains("file:"));assertEquals(project.updatedAt,store.get(project.id).updatedAt);assertFalse("Artifact snapshot is not an inference execution",exported.optBoolean("nativeRendered"));p.getJSONObject("controls").put("strength",.6);assertThrows(IllegalStateException.class,()->OpenPipelineOperations.execute(context,store,"open_pipeline_export_request",p,null));
    }
    @Test public void cog2bFrameClockRequiresOddLatentCountInBothModes()throws Exception {for(int frames:new int[]{9,17,49}){assertEquals(frames,OpenPipelineOperations.validateControls("cogvideox",cogControls().put("numFrames",frames)).getInt("numFrames"));assertEquals(frames,OpenPipelineOperations.validateControls("cogvideox",cogControls().put("mode","video_to_video").put("strength",.8).put("numFrames",frames)).getInt("numFrames"));}assertThrows(IllegalArgumentException.class,()->OpenPipelineOperations.validateControls("cogvideox",cogControls().put("numFrames",13)));assertThrows(IllegalArgumentException.class,()->OpenPipelineOperations.validateControls("cogvideox",cogControls().put("mode","video_to_video").put("strength",.8).put("numFrames",13)));}
}
